quests[53335] = { id = 53335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: War Resources", progress = "Our forces are gathering for the battle to come. Do you wish to help further our efforts?", completion = "A generous donation. I will let the commander know of your contributions." }
quests[53336] = { id = 53336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Sabertusk Empress", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a ferocious Sabertusk Empress, the strongest and most vicious of all sabertusks in Zuldazar. \n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", completion = "Thank ya, champion. That be one less threat to the area.", objectives = "Slay a Sabertusk Empress", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53337] = { id = 53337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Prime Thumpknuckle", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a Prime Thumpknuckle, the largest and most dangerous of all the wild gorillas.\n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", completion = "You faced down those Thumpknuckles? That's worth a lot to us. Thank ya.", objectives = "Slay a Prime Thumpknuckle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53338] = { id = 53338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove your Worth", description = "See many Alliance out there, {race}? We're getting reports of more and more Alliance showing up here on Zandalar.\n\nDon't forget that this is a W-A-R. Prove your worth, and get out there and slay as many of them as you can.\n\nFor the Horde!", completion = "A good first start, here's something from our engineers that may prove useful...", objectives = "Enable War Mode and slay 1 Alliance Player within the world.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
