quests[53342] = { id = 53342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Molten Core", description = "We'll need a fragment o' the core tae repair the Black Anvil an' who knows how much dark iron tae achieve the necessary purity. Thaelin can figure that part out.\n\nIn fact, I think he oughta go with ye tae get yerself a Fragment o' the Molten Core.\n\nIt's too dangerous tae go deep via mole machine, but he's got a hardy tank that can get ye the rest o' the way from the top.\n\nTalk tae me when yer ready.", progress = "Sometimes it's hard tae understand Thaelin's ramblin's, but he's a smart one.", completion = "Good work, {name}. That fragment gets us a long way toward fixin' the Black Anvil.", objectives = "Speak with Moira at the Stormwind Embassy to travel to Molten Core and retrieve a Fragment of the Molten Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53343] = { id = 53343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Censership" }
quests[53344] = { id = 53344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iconoclasm" }
quests[53345] = { id = 53345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder and Provisions" }
quests[53346] = { id = 53346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trogg Tromping" }
quests[53347] = { id = 53347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bumbles the Bee", progress = "Were you able to find it? I think it's in a purple bottle.", completion = "Alright! This is exactly what we needed.", objectives = "Locate Raimond's Secret Ingredient.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53348] = { id = 53348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Thundersnout", description = "Thundersnout is the largest of the boars in the valley. She poses a serious threat to our troop movements in the south.\n\nAs such, Centurion Kaga Warmstone has issued a bounty for proof of her demise.\n\nThundersnout's location is near the Briarback kraul, so beware the local quilboar!", progress = "Yes?", completion = "The death of the matriarch means the next generation of boars will be delayed. Nice work.", objectives = "Deliver Thundersnout's Snout to Centurion Kaga Warmstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53349] = { id = 53349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53351] = { id = 53351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The MOTHERLODE!!: Ironfoe", description = "Mogul Razdunk has always been a jealous sort, wishin' he was Gallywix or better.\n\nBut he's the worst sort o' greedy. He won't stop at anythin' tae achieve his ends, nae matter the cost.\n\nIt was a bold move even fer him tae strike at us in Blackrock Depths.\n\nHe should've knaewn he was goin' too far. Kill that covetous wretch an' bring the hammer back where it belongs.\n\nYou'll find him in Kezan. Somewhere he calls \"The Motherlode,\" likely with too many exclamation points.", progress = "I wish I could see look on his face as ye rip the hammer away from his cold hands.", completion = "Serves him right fer stealin' one o' our most sacred artifacts. I hope he squirmed.", objectives = "Recover Ironfoe from Mogul Razdunk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53352] = { id = 53352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firelands", description = "Alright, the hard part should be behind us, {name}.\n\nNow, we just need tae take that Molten Core fragment ye recovered into Firelands an' charge it up by Ragnaros' old swimmin' pool.\n\nDinna worry! I'm sendin' Anvil-Thane Thurgaden with ye.\n\nJust give me a nudge when ye're ready.", progress = "I hope ye're nae afraid o' a little bit o' fire.", completion = "High Justice Grimstone calls himself the Herald o' Ragnaros now, does he? That traitor will rue the day he turned his back on the Dark Iron dwarves.", objectives = "Speak with Moira at the Stormwind Embassy to travel to the Firelands and empower the Fragment of the Molten Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53353] = { id = 53353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo of Warlord Zaela", description = "Warlord Zaela... another name that stains the tongue just to speak it...\n\nShe was instrumental in freeing Garrosh during his trial when she and her Dragonmaw clan attacked the Temple of the White Tiger.\n\nI am ashamed to say that the dragon Kairozdormu was also involved. We will speak of this no more.\n\nThe temple in Kun Lai Summit is our next destination.", progress = "Some of my kin invite shame upon our name.", completion = "Let us leave this place before it arouses my anger.", objectives = "Defeat the Echo of Warlord Zaela at the Temple of the White Tiger in Kun Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53354] = { id = 53354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo of Gul'dan", description = "To attune this shard to the place you wish to go, we must follow some of its history.\n\nThe first location we will visit is the Dark Portal in the Blasted Lands.\n\nIt was there that Gul'dan used a piece of the Vision of Time to travel between realities.\n\nJoin me there when you are ready.", progress = "The Vision of Time still holds power, it just needs to be unlocked.", completion = "Gul'dan was a pox upon all lands that he set foot upon. His death was well deserved.", objectives = "Defeat the Echo of Gul'dan at the Dark Portal in Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53355] = { id = 53355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo of Garrosh Hellscream", description = "Our final destination will take us to the depths beneath your city of Orgrimmar.\n\nThe way there is barred, but I can get us inside.\n\nMeet me outside the gates of Orgrimmar and we will descend together.", completion = "Yes, this thrums with power! This is precisely what I needed.", objectives = "Meet Anachronos outside the gates of Orgrimmar, then defeat the Echo of Garrosh within the Siege of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53358] = { id = 53358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Hyphen Tech", description = "This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN'T a--dreadlord, really?" }
quests[53359] = { id = 53359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Steelskin Potion", progress = "Some o' da best potions give ya allies a fightin' chance. If ya find any, come an' see me.", completion = "Don't ya be worryin'. I be handlin' these with special care." }
quests[53360] = { id = 53360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Steelskin Potion", progress = "Steelskin Potions are a great source of protection.\n\nIf you should find any in your travels, I'd gladly take them off your hands.", completion = "Wonderful! This is exactly what I was looking for.", objectives = "Gather 2 Steelskin Potions for Chelsea Strand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53361] = { id = 53361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Meaty Haunch", description = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air.\n\nIf you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", progress = "Fresh meat goes a long way. If we're to endure the battle, we've got to be prepared.", completion = "This will last for quite some time.\n\nThank you, {name}.", objectives = "Gather 2 Seasoned Loins for Senedras in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53362] = { id = 53362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Meaty Haunch", progress = "Delicious food provides the nourishment needed to endure what is to come.", completion = "Your donation is most appreciated." }
quests[53363] = { id = 53363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Drums of the Maelstrom", progress = "In battle, those who are victorious march to the beat of the same drum.\n\nWhat say we provide our allies with a little drumming of our own?", completion = "Finely crafted, taught hide... is this bone? This work is quite masterful.\n\nI'll make sure these are put to good use.", objectives = "Donate 2 Drums of the Maelstrom to Charlane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53364] = { id = 53364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Drums of the Maelstrom", progress = "Soldiers rely upon each other in battle. What do say we provide them with a little boost on the battlefield?", completion = "The craftsmanship on these drums are extraordinary.\n\nI'll be sure to pass these along. Thank you, {name}." }
quests[53365] = { id = 53365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Battle Flag: Rallying Swiftness", progress = "Our allies rally beneath our banners on the battlefield. Help us provide them the speed and precision necessary to break the frontline.", completion = "What beautiful work." }
quests[53366] = { id = 53366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Battle Flag: Rallying Swiftness", progress = "The finest threading and craftsmanship create the most beautiful standards.\n\nHave you any to offer?", completion = "Truly magnificent.\n\nOur allies will rally beneath our colors on the battlefield.", objectives = "Gather 2 Battle Flag: Phalanx Defense for Faella in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53367] = { id = 53367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Organic Discombobulation Grenade", progress = "Nothing provides an advantage like the ability to spot your enemies from a great distance. You got anything of the kind?", completion = "Wonderful work, {name}. And lighter than I expected. Magnificent." }
quests[53368] = { id = 53368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Organic Discombobulation Grenade", progress = "Distance, accuracy, quality metal, and top-notch craftsmanship--nothing else will do.\n\nI don't suppose you're able to get your hands on a few of these?", completion = "Spectacular! This is just what I was looking for." }
quests[53369] = { id = 53369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Loh Go", description = "Hello, {name}! We tortollans grow up hearing the stories of Loh, a tortollan who had many adventures. These stories help to challenge a young tortollan's mind as they try to figure out how Loh would make his way through any given adventure.\n\nCare to give it a try?", objectives = "Learn how to guide Loh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53370] = { id = 53370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Hour of Reckoning", description = "Champions of the Alliance, \n\nAt last the time has come for us to reclaim what is rightfully ours! Our final push to retake Lordaeron Keep shall commence at dawn. \n\nThe Horde and their Warchief must answer for their crimes!", completion = "The Horde will pay for what they've done.", objectives = "Meet Master Mathias Shaw in Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53371] = { id = 53371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Bee Friends", description = "We just need to collect some slime from the animated honey creatures that are still roaming around the farm.\n\nIf you can bring back a few vials of that, we can put all our ingredients together and give the mixture to Bumbles.\n\nWe should only feed him once a day, or he might get sick like some of the other bees.\n\nWe're gonna have him all healed up in no time!", progress = "Did you collect enough of the slime?", completion = "He's looking so much better!", objectives = "Collect 8 Vials of Honey Slime and mix them with Raimond's Secret Ingredient to make Mildenhall's Growth Formula, then feed it to Bumbles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53372] = { id = 53372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Hour of Reckoning", description = "Champions of the Horde, the time has come. \n\nThe Alliance seek to overthrow the Undercity and are laying siege to Lordaeron Keep. You are to report High Overlord Saurfang at once.\n\nMake haste, Brill has already fallen and there is no time to spare.", completion = "The Alliance moves against the Undercity, seeking retribution for the burning of Teldrassil.\n\nWe will not allow them to take what is ours, {class}.", objectives = "Speak to High Overlord Saurfang inside Grommash Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53374] = { id = 53374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BFA 111-119 E" }
