quests[53498] = { id = 53498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staying Power" }
quests[53500] = { id = 53500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who enjoys caves and such! We have many dark corners in Stormwind to explore.\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", progress = "Greetings.", completion = "Welcome tae Stormwind. Too much sun out here if ye ask me.\n\nI'm off tae seek adventure! An' somewhere a bit darker.", objectives = "Talk to Chromie in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53502] = { id = 53502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", progress = "Another world... another time... this is an age of wonder.", completion = "Lots of new things to cut around here, if you know what I mean. I mean I like to cut things.\n\nDo you like to cut things? Maybe we can cut things together one day.", objectives = "Talk to Chromie in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53520] = { id = 53520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detonate!" }
quests[53549] = { id = 53549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty Bag" }
quests[53550] = { id = 53550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change in Leadership", description = "In my experience people do not like to be driven from their homes.\n\nWhile normally we would crush them with the might of the Horde, we do not have time to carry out a lengthy campaign against these creatures.\n\nThey will look to their leaders for hope, inspiration, and guidance. They will find none.\n\nYou are the instrument of my will, {name}. Make them submit to it.", objectives = "Defeat Elder Brolg, Gren Tornfur and Elder Brownpaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53551] = { id = 53551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elves in the Machine", description = "The Horde have already set up camp here. But we can still strike back.\n\nTheir war machines are terrible to behold, but they are still machines. And machines do not work well when you go in and hack up a bunch of their inner workings.\n\nIf we can sabotage but a few of them, that could mean dozens of lives saved.\n\nLet us make the most of this opportunity.", progress = "We need to destroy those demolishers!", completion = "We have done what we can here. Come, we must finish the mission.", objectives = "Sabotage 5 Horde Demolishers in Blackwood Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53552] = { id = 53552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wicked Kegger" }
