quests[53563] = { id = 53563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BFA 111-119 E" }
quests[53566] = { id = 53566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Dwarves", description = "I can't thank ye enough, {name}. Without yer help, Ironfoe would be lost tae us and the Black Anvil could've ne'er been made whole.\n\nBut even more than that, ye've proven to every Dark Iron in the mountain what it means tae be part o' somethin' bigger. Tae be part o' the Alliance.\n\nThe time has come tae let King Anduin know that my people stand with him.", completion = "By securing the Dark Iron clan's commitment to the Alliance, you have brought renewed strength to our cause. \n\nQueen-Regent Thaurissan and I are both in your debt. Thank you, {name}.", objectives = "Speak with Aysa Cloudsinger at the Stormwind Embassy to hear the end of this tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53583] = { id = 53583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adapting Our Tactics", description = "For our best chance to win this war, we must continue to learn and adapt new strategies. There are opportunities for advancement all around us, but they require dedication and perseverance.\n\nI've collected a list of potential research opportunities for you to review. Any one of these might feel small on its own, but together they might just be all the advantage we need.\nLet me know which ones you would like us to pursue.", progress = "Did you make a decision yet?", completion = "Excellent. We will see to it right away.", objectives = "Talk to Alleria Windrunner to start researching an upgrade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53602] = { id = 53602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adapting Our Tactics", description = "This war will not be won with strength and might alone. Take in your surroundings while you fight and turn it into an advantage against the enemy.\n\nI have a list of modifications for you to choose from. Any one of these might feel small on its own, but together they might just be all the advantage we need.\n\nLet me know what you would like us to pursue.", progress = "What is your decision?", completion = "Excellent. We will see to it right away.", objectives = "Talk to Eitrigg to start researching an upgrade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53604] = { id = 53604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing Them Out", description = "They have amassed an army before us, {name}. But it is no matter. The Horde war machine will not be stopped.\n\nGo into The Master's Glaive and dispatch their warriors. Their sentinels. Any who would raise a blade against my soldiers. \n\nClear out the petty rabble that seeks to delay the inevitable.", completion = "We are one step closer to our goals.", objectives = "Slay Night Elf forces in The Master's Glaive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53605] = { id = 53605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Glaive Misunderstanding", description = "The kaldorei have brought their siege weaponry to the field. They are currently using it to oppose mine.\n\nWe need these demolishers to reach Teldrassil if we hope to stand any chance of capturing it. Go and destroy their glaive throwers as swiftly as you are able.\n\nThey think they will stop my advance here. They are mistaken. Show them the gravity of their error, {name}.", completion = "This was an easy victory. Do not expect it to be this simple in the future. Malfurion will return with his forces, but until then let's press on.", objectives = "Destroy glaive throwers in The Master's Glaive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53606] = { id = 53606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Inspiration", description = "Nothing rallies the Horde more than their banner standing in the ruin of an enemy stronghold.\n\nGo to Blackwood Den, take the territory there, raise the Horde banners and let none question our dominance over this land.", completion = "This is not a time for subtle gestures.", objectives = "Plant 3 Horde Banners in Blackwood Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53608] = { id = 53608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Horde War Machine", description = "You heard the warchief! We got Azerite shooting outta those ruins over there and night elves tryin' to snag it.\n\nGet to those ruins and collect some of the stuff. This whole attack is done for if the night elves get their hands on that Azerite!", completion = "That should do it! The night elves won't know what hit 'em.", objectives = "Collect Azerite from 6 Azerite Deposits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53609] = { id = 53609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Very Clear Message", description = "The Alliance got to the Azerite here before us, the place is crawling with night elves!\n\nKill as many of them as you can see, we gotta make sure none of them deliver even an ounce of Azerite to the Alliance!", completion = "Whew, that was a close call. Those night elves shoulda just ran away when they had the chance!", objectives = "Kill 10 night elf forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53610] = { id = 53610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Driving Them Out", description = "This is it, {name}. \n\nLor'danel is all that stands in our way before we capture Darnassus and reclaim Kalimdor. \n\nRout the defenders. We cannot risk allowing a single enemy to escape until we have secured control over the World Tree.\n\nI want this place in order by the time the Warchief arrives.", completion = "This has almost been too easy.", objectives = "Slay 15 Lor'danel defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53616] = { id = 53616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knives of the Forsaken", description = "Tread carefully. All is not as it seems. The butchers who did this still skulk within Astranaar.\n\nIf you find them, give them what they deserve, {name}.", progress = "Has justice been served upon Sylvanas's assassins?", completion = "It is no less than those filthy creatures deserved.", objectives = "Slay 8 Forsaken Assassins in Astranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53617] = { id = 53617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercy for the Mad", description = "The ruin wrought by the Horde is driving the children of the forest mad.\n\nChief among them are Blackwood furbolgs. They have given into the madness and are a threat to everyone. If left to their madness they could strike us from behind while our forces engage the Horde. \n\nIt pains me to ask this, but please, when you are in the Twilight Vale, put these creatures out of their misery before they endanger anyone else.", completion = "It is a tragedy that so many furbolgs had to perish, but it was necessary. In their madness they could attack our own people leaving us fighting a battle on two fronts.", objectives = "Slay 10 frenzied Blackwood furbolgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53619] = { id = 53619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Denial", description = "This substance, Azerite, is hurting Onu... and the Horde seem eager to collect it for themselves.\n\nWe must not let that happen. Collect as much Azerite as you can find. Ensure the Horde do not retrieve it.", completion = "Excellent work... this Azerite is a powerful substance indeed. We must not allow the Horde to get their hands on it.", objectives = "Collect Azerite from 6 Azerite Deposits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53621] = { id = 53621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Horde Allowed", description = "The Horde forces in this area are trying to collect as much Azerite as possible. No doubt they intend to weaponize it.\n\nSlay any Horde forces you can find. They must not be allowed to get their hands on this Azerite!", completion = "We will end the Horde's invasion, here and now. Without this Azerite, they cannot win.", objectives = "Kill 10 Horde soldiers in Nazj'vel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53622] = { id = 53622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending Lor'danel", description = "The Horde have invaded from the North! You must protect Lor'danel, {name}. \n\nHelp our forces push back this attack!\n\nI will try to intercept the Warchief. This is our final chance to stop her. Report to Commander Summermoon in my absence.", completion = "Your aid is welcome, but I fear the Horde is relentless. Their forces are not slowing down.", objectives = "Take out Horde forces in Lor'danel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53623] = { id = 53623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth Dungeon Reward Quest" }
quests[53627] = { id = 53627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift of Azerite", description = "I think we got a handle on things here. You gotta bring all this Azerite back to Zarvik Blastwix at the main camp!\n\nHe's gonna know just how to use this stuff to really take down the Alliance.", completion = "Azerite! For me? You shouldn't have! \n\nJust kidding, of course you should have.", objectives = "Deliver Azerite to Zarvik Blastwix in Blackwood Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53641] = { id = 53641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Stromgarde (Arathi)" }
quests[53665] = { id = 53665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready for Battle", description = "Greetings, {name}.\n\nOur recruits are eager to join you on the battlefield.", progress = "Looking for a few recruits?", completion = "With our allies fighting by your side the battlefield is ours for the taking.", objectives = "Speak with Throk to recruit an ally from the Barracks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53666] = { id = 53666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Up!", description = "Ah, {name}. Word spreads quickly around here.\n\nUnfortunately, with all these orders coming in I can't afford to talk right now.\n\nIf you're interested in learning more about the armory Fennick can help you with that. He's just outside.", completion = "What? Old Drom'kal's too busy for ya? I'm not surprised.\n\nAt least now that the armory's up and 'runnin' we can work on gettin' our allies some better gear.", objectives = "Speak with Fennick to learn what the Armory has to offer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53667] = { id = 53667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Workshop", description = "You must be the new <guy/gal> around here. Name's Margie. And that over there, that's Pixy.\n\nWe run a tight crew here at the workshop. So, if you ever need anything, you know where to find us.\n\nNow, I suggest you head on over and check in with Pixy. She can show you what we have to offer.", progress = "I'm workin' here.", completion = "Well that was quick!\n\nLike I said before, if ya need anything you know where to find us.", objectives = "Speak with Pixy Hackwrench to learn what the Workshop has to offer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53668] = { id = 53668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flightgineer's Network", description = "Now that we control High Perch the skies are ours!\n\nI've laid out a few plans for expanding our routes in this here note. If you'd be so kind as to deliver it to our commander, I'm sure they'll be pleased with our progress.\n\nLet me know when you're ready and l'll send ya on your way.", completion = "Our goblin friend assures me he is able to expand our travel network as long as we hold key positions.\n\nLooks like we've got our work cut out for us.", objectives = "Deliver Flightgineer Krazzle's Note to your commander in Ar'gorok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53669] = { id = 53669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Altar's Power", description = "Looks like construction on the Altar of Storms is complete.\n\nI'm sure Meredith would be more than happy to show you what mysterious powers lie within.", progress = "Yea?", completion = "Huh. Would ya look at that.\n\nI can feel the energy comin' off that thing from here!", objectives = "Speak with Meredith the Crone to learn what the Altar of Storms has to offer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53670] = { id = 53670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Newstead", description = "Nothing penetrates an enemy's front line like a fierce rider and a well-trained beast. Now that we control Newstead, one of our riders in particular has focused his efforts on training us a few kodos.\n\nGo, check in with Tanauk and find out what these beasts are capable of.", progress = "What are you waiting for?", completion = "Powerful beasts, aren't they?", objectives = "Speak with Kodo Rider Tanauk to learn about the beasts he's been training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53671] = { id = 53671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Circle's Power", description = "With the Circle of Elements under our control there are opportunities to harness the powers of the elements.\n\nKraga understands these powers quite well. I suggest speaking with her.", progress = "Have you found what you were looking for?", completion = "Such power is not to be taken lightly.", objectives = "Speak with Kraga Tidefury to learn what she has to offer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53672] = { id = 53672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready for Battle", description = "Welcome to the warfront, {name}.\n\nOur recruits are eager to join you on the battlefield.\n\nA good place to start would be Ralston. I'm sure he's got a few who could learn much fighting by your side.", progress = "Looking for a few recruits?", completion = "With our allies rallying by your side on the battlefield I have no doubt we will remove the Horde threat from Arathi.", objectives = "Speak with Ralston Karn to recruit an ally from the Barracks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53673] = { id = 53673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Up!", description = "What've we got 'ere? A fresh, young <lad/lass> lookin' ta help better prepare our allies fer battle? Well then, Jonathan's always lookin' for a bit o' help ta keep our armory orders in full swing.\n\nI'd offer ta walk ya over, but I've got me hands full here. Ye can find him just over yonder.", completion = "Hmm? Ah, yes.\n\nEverything in order? Armory resources looking good, yes?", objectives = "Speak with Jonathan Flynn to learn what the Armory has to offer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53674] = { id = 53674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Altar's Power", description = "With contributions in full swing it's no surprise the Altar of Kings was built with such haste.\n\nI suggest wandering over that way. You might be surprised to see what the Altar has to offer.", progress = "Yes?", completion = "My goodness! What an incredible source of power.", objectives = "Speak with Altarite Jesse Taylor to learn what the Altar of Kings has to offer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53675] = { id = 53675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Workshop", description = "Welcome to the workshop!\n\nI told Grumble I thought it best for me ta protect him from unnecessary distractions, but I think it may benefit all of us if ye get a peek at what we're doin' 'round here.\n\nWhy don't ye head on over and see what we have ta offer.", progress = "How can I help ye?", completion = "Ah, wonderful. I take it ye got a good look at our work.", objectives = "Speak with Grumble to learn what the Workshop has to offer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53676] = { id = 53676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Circle's Power", description = "The Circle of Elements presents us with an opportunity to harness great power. One of our allies, Justine, has great knowledge into what this might mean for our efforts.\n\nSeek her out. It's time you discovered the power of the elements.", progress = "Discover anything?", completion = "The enemy stands little chance.", objectives = "Speak with Justine Frost to learn what she has to offer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53677] = { id = 53677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Newstead", description = "Control of Newstead has allowed our forces to advance. It's also provided Vindicator Banra ample room to continue training his elekk for battle.\n\nI suggest you speak with him to learn more about what these magnificent beasts are capable of.", progress = "Remain vigilant.", completion = "Truly magnificent. Don't you agree?", objectives = "Speak with Vindicator Banra to learn about the beasts he's been training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53678] = { id = 53678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establishing a Connection", description = "Now that we control High Perch the skies are ours!\n\nI've drafted plans for a flight network that provides our allies safe passage. Please, take these notes and deliver them to our commander at once.\n\nI'm happy to provide you with a gryphon that will deliver you to the base when you are ready.", completion = "Excellent news. I've been assured retaining control of key battlefield positions allows our gryphons to soar through the skies without interruption to various locations.\n\nWe must press our efforts even further.", objectives = "Deliver Grayson's Note to your commander in Stromgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53699] = { id = 53699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gate Crashers" }
quests[53701] = { id = 53701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Drust Cause", description = "Horde armies are pushing into the heart of Drustvar. Hold the line and drive them back to the holes they crawled out of. Kul Tiras is ours!", progress = "We cannot rest while the Horde assault Drustvar!", completion = "The Horde got what they deserved.", objectives = "Repel the Horde forces assaulting Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53704] = { id = 53704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Too Sober Citizens Brigade" }
quests[53706] = { id = 53706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvage the Supplies" }
quests[53707] = { id = 53707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke the Supplies" }
quests[53711] = { id = 53711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sound Defense", description = "Horde forces are attacking Tiragarde Sound. Make them regret every footstep upon our soil!", progress = "The Horde dares to assault us here in Boralus?! Our response must be swift, massive, and merciless!", completion = "Everyone in Boralus cheered when we saw the explosions up on that airship! The Horde will think twice before assaulting Boralus again.", objectives = "Repel the Hordes forces assaulting Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53712] = { id = 53712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfriendly Skies" }
quests[53713] = { id = 53713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wet Work: Bridgeport" }
quests[53714] = { id = 53714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apothecary Jerrod" }
quests[53715] = { id = 53715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firewarden Viton Darkflare" }
quests[53716] = { id = 53716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastpoint Emergency" }
quests[53717] = { id = 53717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hold the Highland" }
quests[53719] = { id = 53719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance of the Zandalari", description = "It is decided, {name}.\n\nDe Zandalari will join de Horde.\n\nOur path together has been a long and difficult one. We have lost much together. De Horde has sacrificed for de Zandalari, and vice versa. I can do nothing to honor that commitment except pledge our loyalty.\n\nCollect your Warchief and send them to my throne. I will extend de offer myself.", completion = "Without you, none of this would have been possible. You have done well, my champion.", objectives = "Bring the Zandalari into the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53720] = { id = 53720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance of Kul Tiras", description = "It is time for her maiden voyage, {name}.\n\nThis aptly named vessel will carry us and her crew across the vast sea to Stormwind Harbor. There we will meet Anduin and I will seal the pact we made so many moons ago.\n\nKul Tiras will stand with the Alliance so long as I am Lord Admiral.\n\nThank you for your assistance in this endeavor.", completion = "I accept this gesture in the spirit in which it was made, {name}.\n\nThe Kul Tirans have been valuable allies, and now we have a physical manifestation of that bond.\n\nI thank you for your continued support of the Alliance. We continue to grow with your aid.", objectives = "Sail to Stormwind Harbor and present Anduin with his gift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53721] = { id = 53721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Zandalari", description = "You have faced many challenges in your time among de Horde. You carried de pride of de Zandalari on your shoulders and triumphed!\n\nReturn to me. I wish to recognize de example you have set for us all.", completion = "Wear dis armor with pride, {name}. You now stand among de greatest champions of de Zandalari.", objectives = "Meet Queen Talanji at the Golden Throne in Zuldazar City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53722] = { id = 53722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Kul Tiran", description = "Gossip in Boralus has oft reached my ears of your exceptional conduct, {name}.\n\nMeet me before the keep. I wish to commend your efforts on behalf of Kul Tiras.", completion = "Wherever the winds take you, know that you take the spirit of Kul Tiras with you.\n\nWear our colors with pride, {name}.", objectives = "Meet Katherine Proudmoore in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53724] = { id = 53724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Hunter Mutumba" }
quests[53725] = { id = 53725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A People Shattered", description = "While the monument here was intended to honor the fallen members of the Shattered Sun, it quickly took on a second meaning for the sin'dorei.\n\nIt was not far from here that we lost one of our greatest heroes: Anasterian Sunstrider, the last king of Quel'Thalas. He led our final effort against the Scourge and personally crossed blades with Arthas himself. As we remember the sacrifices it took to reclaim this land, we also remember the sacrifices made in its defense.", progress = "Yes?", completion = "Never forget the lives that were lost here. Both to the Scourge, and to their own misguided kin.", objectives = "Light the final flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53726] = { id = 53726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechinations" }
