quests[53733] = { id = 53733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 A" }
quests[53734] = { id = 53734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk Among Ghosts", description = "Every year, we ask a champion of our people to perform an act of remembrance in honor of those who fell to the Scourge. Lady Liadrin has performed this ritual, as have I, among others. This year, I am honored to give the task to you.\n\n<The Regent Lord hands you an ornate lantern.>\n\nThis lantern carries a flame born of the Sunwell. I would ask that you bring it to locations that were significant to the fall of the Sunwell and of Quel'Thalas, and to light the memories we cannot forget.", completion = "This land will never recover from the damage that was done here. But we lost so much more than land that day.", objectives = "Meet Lor'themar in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53735] = { id = 53735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First to Fall", description = "Arthas cut through the land itself to get to the Sunwell. The Dead Scar is a constant reminder of that desecration. Where it starts is where our first line of defense attempted to hold the Scourge at bay. It is where the first blood was spilled.\n\nIt was a slaughter.\n\nTake the lantern to the base of the Dead Scar, and use its light to reveal the memories of what happened there.", progress = "Yes?", completion = "<Lor'themar stands quiet for a moment.>\n\nElor bindel felallan morin'aminor.", objectives = "Witness the fall of the first defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53736] = { id = 53736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lament of the Highborne", description = "The next memory...\n\nForgive me. For many of our people, it was when we realized death was coming for us.\n\nA memorial to a particular defender lies to the west, in the place of her home. The light there has no doubt attracted some of the area's lingering souls. Clear them out, and then relight the flame.", completion = "Sylvanas and the Farstriders sacrificed more than most of us. Sometimes I must remind myself of that fact, given the current state of affairs.", objectives = "Light the second memorial flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53737] = { id = 53737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day Hope Died", description = "The Ranger-General fell just east of Fairbreeze Village, where she was holding the line to protect the civilians as they retreated to Silvermoon. If it wasn't for her, our people would number even less than we do now.\n\nShine the lantern upon the battlefield, and witness how her forces ultimately broke under Arthas's personal assault.", progress = "<Lor'themar is silent.>", completion = "In the words of one of the more poetic retellings:\n\nAs her defenders fell, with anguish she cried, \"Shindu fallah na, Sin'dorei.\"\n\nShe was a true Ranger-General until her last breath. May Silvermoon never forget her bravery in life.", objectives = "Witness the fall of the Ranger-General.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53738] = { id = 53738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense of Quel'Danas", description = "With our best defenders defeated and the line broken, Arthas made quick work of Silvermoon's remaining forces and tore through the city.\n\nThis is where we part ways. I must return to Silvermoon before Halduron starts sending rangers to search for me.\n\nThe dragonhawk master in Fairbreeze Village has orders to fly you to Quel'Danas. Someone much more familiar with the events on the island will meet you there.", completion = "Are you ready, {name}?", objectives = "Meet with Lady Liadrin in Quel'Danas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53752] = { id = 53752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shell Outs" }
